Chapter.Code:
struct Particle
{
    Vec3 Position;
    Vec3 Velocity;
    float Mass;
    float Lifetime;
};

std::vector<Particle> particles;

for (Particle& p : particles)
{
    RenderDebugParticle(
        p.Position,
        p.Velocity,
        p.Mass,
        p.Lifetime);
}

