    float* RotZ;
    float* RotW;

    float* ScaleX;
    float* ScaleY;
    float* ScaleZ;
};

struct Character
{
    // hot every frame
    Vec3 Position;
    Vec3 Velocity;
    float Health;

    // cold
    std::string DisplayName;
    AssetHandle Portrait;
    std::string Biography;
    DebugMetadata Debug;
};

